insert into public.cases (id, slug, title, specialty_id, difficulty, tags, organization_id)
values ('07ad628b-7946-5567-b916-23a2176331d5', 'ed-thunderclap-headache', 'Worst headache of my life',
        (select id from public.specialties where slug = 'emergency'),
        4, array['headache', 'neurology', 'acute', 'de-escalation']::text[], 'da25c93a-d2d1-5ef8-9259-a5e38dbe8432')
